const fmt = v => v > 0 ? v.toLocaleString("es-CO",{maximumFractionDigits:1}) : "—";

// ── LOGIN SCREEN ─────────────────────────────────────────────────────────────
function LoginScreen({ onLogin }) {
  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const handleLogin = () => {
    setErr(""); setLoading(true);
    setTimeout(() => {
      setLoading(false);
      const u = DIST_USERS[email.toLowerCase()];
      if (u && u.pass === pass) {
        onLogin({type:"distribuidor", email: email.toLowerCase(), name: u.name, region: u.region});
      } else {
        setErr("Correo o contraseña incorrectos.");
      }
    }, 700);
  };

  return (
    <div style={{minHeight:"100vh",background:"#0a0f1e",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",fontFamily:"'DM Sans', sans-serif",padding:20}}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=DM+Mono:wght@500;700&display=swap');*{box-sizing:border-box}`}</style>

      {/* Logo */}
      <div style={{marginBottom:32,textAlign:"center"}}>
        <div style={{background:"#fff",borderRadius:16,padding:"12px 24px",display:"inline-block",marginBottom:12,boxShadow:"0 4px 24px rgba(0,0,0,0.4)"}}>
          <img src={LOGO} alt="MeUp" style={{height:48,display:"block"}} />
        </div>
        <div style={{fontSize:13,color:"#64748b",letterSpacing:"0.1em",textTransform:"uppercase"}}>Portal de Distribuidores</div>
      </div>

      {/* Card */}
      <div style={{background:"#111827",border:"1px solid #1e293b",borderRadius:20,padding:"36px 40px",width:"100%",maxWidth:400,boxShadow:"0 20px 60px rgba(0,0,0,0.5)"}}>
        <h2 style={{color:"#f1f5f9",fontSize:20,fontWeight:800,margin:"0 0 6px",letterSpacing:"-0.02em"}}>Acceder al inventario</h2>
        <p style={{color:"#64748b",fontSize:13,margin:"0 0 28px"}}>Ingresa con tus credenciales de distribuidor</p>

        <div style={{marginBottom:18}}>
          <label style={{display:"block",fontSize:12,fontWeight:600,color:"#94a3b8",marginBottom:6,letterSpacing:"0.04em",textTransform:"uppercase"}}>Correo electrónico</label>
          <input
            value={email} onChange={e=>{setEmail(e.target.value);setErr("");}}
            onKeyDown={e=>e.key==="Enter"&&handleLogin()}
            placeholder="tu@empresa.com"
            style={{width:"100%",padding:"11px 14px",background:"#1e293b",border:"1px solid #334155",borderRadius:10,color:"#f1f5f9",fontSize:14,fontFamily:"inherit",outline:"none"}}
          />
        </div>
        <div style={{marginBottom:err?14:24}}>
          <label style={{display:"block",fontSize:12,fontWeight:600,color:"#94a3b8",marginBottom:6,letterSpacing:"0.04em",textTransform:"uppercase"}}>Contraseña</label>
          <input
            type="password" value={pass} onChange={e=>{setPass(e.target.value);setErr("");}}
            onKeyDown={e=>e.key==="Enter"&&handleLogin()}
            placeholder="••••••••"
            style={{width:"100%",padding:"11px 14px",background:"#1e293b",border:"1px solid #334155",borderRadius:10,color:"#f1f5f9",fontSize:14,fontFamily:"inherit",outline:"none"}}
          />
        </div>
        {err && <div style={{fontSize:12,color:"#f87171",marginBottom:16,padding:"8px 12px",background:"#450a0a",borderRadius:8}}>⚠️ {err}</div>}

        <button onClick={handleLogin} disabled={loading||!email||!pass} style={{
          width:"100%",padding:"13px",background: loading||!email||!pass ? "#1e293b" : "linear-gradient(135deg,#3b82f6,#8b5cf6)",
          color: loading||!email||!pass ? "#475569" : "#fff",
          border:"none",borderRadius:12,fontSize:14,fontWeight:700,cursor: loading||!email||!pass?"not-allowed":"pointer",
          fontFamily:"inherit",letterSpacing:"0.02em",transition:"opacity 0.15s",
        }}>{loading ? "Verificando..." : "Ingresar →"}</button>

        <div style={{marginTop:20,padding:"12px 14px",background:"#0f172a",borderRadius:10,border:"1px solid #1e293b"}}>
          <div style={{fontSize:11,color:"#64748b",marginBottom:6,fontWeight:600}}>💡 Credenciales de prueba:</div>
          <div style={{fontSize:11,color:"#475569",fontFamily:"'DM Mono',monospace",lineHeight:1.8}}>
            dist1@empresa.com / dist2026<br/>
            ventas@marmoles.com / marmoles1
          </div>
        </div>
      </div>
      <div style={{marginTop:20,fontSize:11,color:"#334155"}}>¿Necesitas acceso? Contacta a tu asesor MeUp.</div>
    </div>
  );
}

// ── PRODUCT CARD ─────────────────────────────────────────────────────────────
function Card({ p, isVendedor }) {
  const [open, setOpen] = useState(false);
  const cs = CS[p.cat]||CS["Complementarios"];
  const hasNav = p.d1>0||p.d2>0;
  const totalBodega = p.baq+p.cuc;

  return (
    <div onClick={()=>setOpen(!open)} style={{
      background:"#fff",borderRadius:12,cursor:"pointer",
      border:"1px solid #e2e8f0",borderLeft:`4px solid ${cs.accent}`,
      boxShadow:open?"0 6px 24px rgba(0,0,0,0.08)":"0 1px 3px rgba(0,0,0,0.04)",
      transition:"box-shadow 0.15s",overflow:"hidden",
    }}>
      {/* Row */}
      <div style={{display:"flex",alignItems:"center",gap:10,padding:"11px 14px",flexWrap:"wrap"}}>
        <div style={{flex:1,minWidth:180}}>
          <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:2}}>
            <span style={{fontSize:10,fontWeight:700,color:cs.label,background:cs.bg,padding:"1px 7px",borderRadius:20,letterSpacing:"0.04em",textTransform:"uppercase",whiteSpace:"nowrap"}}>{p.cat}</span>
            <span style={{fontSize:10,color:"#94a3b8",fontFamily:"'DM Mono',monospace"}}>{p.c}</span>
          </div>
          <div style={{fontSize:13,fontWeight:600,color:"#1e293b",lineHeight:1.25}}>{p.n}</div>
        </div>

        {/* Barranquilla FIRST — highlighted */}
        <div style={{
          background: p.baq>0 ? cs.bg : "#f8fafc",
          border:`1px solid ${p.baq>0 ? cs.accent+"44" : "#e2e8f0"}`,
          borderRadius:9,padding:"6px 12px",textAlign:"center",minWidth:72,
        }}>
          <div style={{fontSize:15,fontWeight:800,color:p.baq>0?cs.accent:"#cbd5e1",fontFamily:"'DM Mono',monospace"}}>{fmt(p.baq)}</div>
          <div style={{fontSize:10,color:"#64748b",marginTop:1}}>🔵 B/quilla</div>
        </div>

        {/* Cúcuta SECOND — muted */}
        <div style={{textAlign:"center",minWidth:58}}>
          <div style={{fontSize:14,fontWeight:700,color:p.cuc>0?"#64748b":"#cbd5e1",fontFamily:"'DM Mono',monospace"}}>{fmt(p.cuc)}</div>
          <div style={{fontSize:10,color:"#94a3b8"}}>Cúcuta</div>
        </div>

        {/* Navigation */}
        {hasNav && (
          <div style={{background:"#eff6ff",border:"1px solid #bfdbfe",borderRadius:9,padding:"6px 12px",textAlign:"center",minWidth:72}}>
            <div style={{fontSize:14,fontWeight:700,color:"#1d4ed8",fontFamily:"'DM Mono',monospace"}}>{fmt(p.d1+p.d2)}</div>
            <div style={{fontSize:10,color:"#3b82f6"}}>🚢 tránsito</div>
          </div>
        )}

        {/* Reservas — vendedor only */}
        {isVendedor && p.res>0 && (
          <div style={{background:"#fff7ed",border:"1px solid #fed7aa",borderRadius:9,padding:"6px 12px",textAlign:"center",minWidth:64}}>
            <div style={{fontSize:14,fontWeight:700,color:"#c2410c",fontFamily:"'DM Mono',monospace"}}>{fmt(p.res)}</div>
            <div style={{fontSize:10,color:"#ea580c"}}>🔒 reservas</div>
          </div>
        )}

        <div style={{fontSize:11,color:"#cbd5e1",transform:open?"rotate(180deg)":"none",transition:"transform 0.2s",flexShrink:0}}>▾</div>
      </div>

      {/* Expanded */}
      {open && (
        <div style={{margin:"0 14px 14px",padding:14,background:cs.bg,borderRadius:10,display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))",gap:10}}>
          <div style={{background:"#fff",borderRadius:9,padding:"12px 14px",boxShadow:"0 1px 4px rgba(0,0,0,0.06)"}}>
            <div style={{fontSize:10,fontWeight:700,color:cs.label,marginBottom:5,textTransform:"uppercase",letterSpacing:"0.05em"}}>🔵 Barranquilla</div>
            <div style={{fontSize:24,fontWeight:900,color:p.baq>0?cs.accent:"#94a3b8",fontFamily:"'DM Mono',monospace"}}>{fmt(p.baq)}</div>
            <div style={{fontSize:11,color:"#64748b",marginTop:2}}>{p.u} disponibles</div>
          </div>
          <div style={{background:"#fff",borderRadius:9,padding:"12px 14px",boxShadow:"0 1px 4px rgba(0,0,0,0.06)"}}>
            <div style={{fontSize:10,fontWeight:700,color:"#475569",marginBottom:5,textTransform:"uppercase",letterSpacing:"0.05em"}}>⚪ Cúcuta</div>
            <div style={{fontSize:24,fontWeight:900,color:p.cuc>0?"#475569":"#94a3b8",fontFamily:"'DM Mono',monospace"}}>{fmt(p.cuc)}</div>
            <div style={{fontSize:11,color:"#64748b",marginTop:2}}>{p.u} disponibles</div>
          </div>
          {hasNav && (
            <div style={{background:"#fff",borderRadius:9,padding:"12px 14px",boxShadow:"0 1px 4px rgba(0,0,0,0.06)"}}>
              <div style={{fontSize:10,fontWeight:700,color:"#1d4ed8",marginBottom:5,textTransform:"uppercase",letterSpacing:"0.05em"}}>🚢 En Tránsito</div>
              {p.d1>0 && (<div style={{marginBottom:p.d2>0?8:0}}>
                <div style={{fontSize:10,color:"#3b82f6",fontWeight:600}}>Disp. 1 — próximo</div>
                <div style={{fontSize:18,fontWeight:800,color:"#1e40af",fontFamily:"'DM Mono',monospace"}}>{fmt(p.d1)} <span style={{fontSize:11,fontWeight:400}}>{p.u}</span></div>
                {p.eta1 && <div style={{fontSize:10,color:"#2563eb",marginTop:2}}>📅 ETA: {p.eta1}</div>}
              </div>)}
              {p.d2>0 && (<div style={{borderTop:p.d1>0?"1px solid #bfdbfe":"none",paddingTop:p.d1>0?8:0}}>
                <div style={{fontSize:10,color:"#3b82f6",fontWeight:600}}>Disp. 2 — siguiente</div>
                <div style={{fontSize:18,fontWeight:800,color:"#1e40af",fontFamily:"'DM Mono',monospace"}}>{fmt(p.d2)} <span style={{fontSize:11,fontWeight:400}}>{p.u}</span></div>
                {p.eta2 && <div style={{fontSize:10,color:"#2563eb",marginTop:2}}>📅 ETA: {p.eta2}</div>}
              </div>)}
            </div>
          )}
          {isVendedor && p.res>0 && (
            <div style={{background:"#fff",borderRadius:9,padding:"12px 14px",boxShadow:"0 1px 4px rgba(0,0,0,0.06)"}}>
              <div style={{fontSize:10,fontWeight:700,color:"#c2410c",marginBottom:5,textTransform:"uppercase",letterSpacing:"0.05em"}}>🔒 Reservas Activas</div>
              <div style={{fontSize:24,fontWeight:900,color:"#c2410c",fontFamily:"'DM Mono',monospace"}}>{fmt(p.res)}</div>
              <div style={{fontSize:11,color:"#ea580c",marginTop:2}}>Material bloqueado</div>
            </div>
          )}
          {!hasNav && (
            <div style={{background:"#fff",borderRadius:9,padding:"12px 14px",display:"flex",alignItems:"center",justifyContent:"center"}}>
              <span style={{fontSize:12,color:"#94a3b8"}}>Sin material en tránsito</span>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ── MAIN DASHBOARD ───────────────────────────────────────────────────────────
function Dashboard({ user, onLogout }) {
  const [search, setSearch] = useState("");
  const [cat, setCat] = useState("Todos");
  const [filterStock, setFilterStock] = useState(false);
  const [filterNav, setFilterNav] = useState(false);
  const isVendedor = user.type === "vendedor";

  const filtered = useMemo(() => PRODUCTS.filter(p => {
    if (cat!=="Todos" && p.cat!==cat) return false;
    if (filterStock && (p.baq+p.cuc)<=0) return false;
    if (filterNav && (p.d1+p.d2)<=0) return false;
    if (search) {
      const q=search.toLowerCase();
      return p.n.toLowerCase().includes(q)||p.c.includes(q)||p.cat.toLowerCase().includes(q);
    }
    return true;
  }), [search,cat,filterStock,filterNav]);

  const totalBaq = PRODUCTS.reduce((s,p)=>s+p.baq,0);
  const totalCuc = PRODUCTS.reduce((s,p)=>s+p.cuc,0);
  const totalNav = PRODUCTS.reduce((s,p)=>s+p.d1+p.d2,0);
  const totalRes = PRODUCTS.reduce((s,p)=>s+p.res,0);
  const withNav  = PRODUCTS.filter(p=>p.d1+p.d2>0).length;

  return (
    <div style={{minHeight:"100vh",background:"#f8fafc",fontFamily:"'DM Sans',sans-serif"}}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=DM+Mono:wght@500;700&display=swap');*{box-sizing:border-box}input::placeholder{color:#94a3b8}::-webkit-scrollbar{width:5px}::-webkit-scrollbar-thumb{background:#cbd5e1;border-radius:3px}`}</style>

      {/* Header */}
      <div style={{background:"#0f172a",position:"sticky",top:0,zIndex:100,boxShadow:"0 1px 0 rgba(255,255,255,0.06)"}}>
        <div style={{maxWidth:1300,margin:"0 auto",display:"flex",alignItems:"center",gap:16,padding:"0 20px",height:58}}>
          {/* Logo */}
          <div style={{background:"#fff",borderRadius:8,padding:"5px 10px",display:"flex",alignItems:"center"}}>
            <img src={LOGO} alt="MeUp" style={{height:28}} />
          </div>
          <div style={{height:28,width:1,background:"#1e293b"}} />
          <div style={{fontSize:12,color:"#64748b",letterSpacing:"0.04em",textTransform:"uppercase"}}>Inventario en Tiempo Real</div>

          <div style={{flex:1}} />

          {/* View badge */}
          <div style={{
            padding:"5px 12px",borderRadius:20,fontSize:11,fontWeight:700,letterSpacing:"0.04em",textTransform:"uppercase",
            background: isVendedor ? "#1e3a5f" : "#1c1917",
            color: isVendedor ? "#93c5fd" : "#d6d3d1",
            border: `1px solid ${isVendedor ? "#2563eb44" : "#44403c"}`,
          }}>
            {isVendedor ? "👤 Vendedor" : `🏪 ${user.name}`}
          </div>

          {/* Vendedor: link to full sheet */}
          {isVendedor && (
            <a href="https://docs.google.com/spreadsheets" target="_blank" rel="noopener noreferrer" style={{
              display:"flex",alignItems:"center",gap:6,padding:"6px 14px",
              background:"#166534",border:"1px solid #16a34a44",borderRadius:9,
              color:"#86efac",fontSize:12,fontWeight:600,textDecoration:"none",
              transition:"background 0.15s",
            }}>
              📊 Abrir Google Sheet
            </a>
          )}

          {/* Logout for distributors */}
          {!isVendedor && (
            <button onClick={onLogout} style={{
              padding:"6px 14px",background:"transparent",border:"1px solid #1e293b",
              borderRadius:9,color:"#64748b",fontSize:12,fontWeight:600,cursor:"pointer",fontFamily:"inherit",
            }}>Salir</button>
          )}

          <div style={{fontSize:11,color:"#334155"}}>26 Feb 2026</div>
        </div>
      </div>

      <div style={{maxWidth:1300,margin:"0 auto",padding:"22px 20px"}}>
        {/* KPIs */}
        <div style={{display:"grid",gridTemplateColumns:isVendedor?"repeat(4,1fr)":"repeat(3,1fr)",gap:14,marginBottom:22}}>
          {[
            {label:"Stock Barranquilla",val:totalBaq.toLocaleString("es-CO",{maximumFractionDigits:0}),sub:"m² / Und en bodega",icon:"🔵",c:"#0f172a"},
            {label:"Stock Cúcuta",val:totalCuc.toLocaleString("es-CO",{maximumFractionDigits:0}),sub:"m² / Und en bodega",icon:"⚪",c:"#475569"},
            {label:"En Tránsito",val:totalNav.toLocaleString("es-CO",{maximumFractionDigits:0}),sub:`${withNav} referencias · Disp.1 + Disp.2`,icon:"🚢",c:"#1d4ed8"},
            ...(isVendedor?[{label:"Reservas Activas",val:totalRes.toLocaleString("es-CO",{maximumFractionDigits:0}),sub:"bloqueado para clientes",icon:"🔒",c:"#c2410c"}]:[]),
          ].map((k,i)=>(
            <div key={i} style={{background:"#fff",borderRadius:14,padding:"16px 20px",border:"1px solid #e2e8f0",boxShadow:"0 1px 4px rgba(0,0,0,0.04)"}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:8}}>
                <span style={{fontSize:11,fontWeight:600,color:"#64748b",letterSpacing:"0.04em",textTransform:"uppercase"}}>{k.label}</span>
                <span style={{fontSize:18}}>{k.icon}</span>
              </div>
              <div style={{fontSize:28,fontWeight:900,color:k.c,fontFamily:"'DM Mono',monospace",letterSpacing:"-0.02em"}}>{k.val}</div>
              <div style={{fontSize:11,color:"#94a3b8",marginTop:4}}>{k.sub}</div>
            </div>
          ))}
        </div>

        {/* Filters */}
        <div style={{display:"flex",gap:10,marginBottom:16,flexWrap:"wrap",alignItems:"center"}}>
          <div style={{position:"relative",flex:1,minWidth:180}}>
            <span style={{position:"absolute",left:11,top:"50%",transform:"translateY(-50%)",color:"#94a3b8",fontSize:13}}>🔍</span>
            <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar por nombre o código..."
              style={{width:"100%",padding:"9px 10px 9px 33px",border:"1px solid #e2e8f0",borderRadius:10,fontSize:13,fontFamily:"inherit",outline:"none",background:"#fff",color:"#1e293b"}} />
          </div>
          {CATS.map(c=>{
            const active=cat===c;
            const s=CS[c]||{bg:"#f8fafc",accent:"#64748b",label:"#64748b"};
            return (
              <button key={c} onClick={()=>setCat(c)} style={{
                padding:"7px 13px",borderRadius:9,fontSize:11,fontWeight:700,cursor:"pointer",fontFamily:"inherit",
                border:`1px solid ${active?s.accent:"#e2e8f0"}`,
                background:active?s.bg:"#fff",
                color:active?s.label:"#64748b",
                transition:"all 0.15s",textTransform:"uppercase",letterSpacing:"0.04em",
              }}>{c}</button>
            );
          })}
          {[
            {k:"filterStock",label:"Con stock",st:filterStock,fn:()=>setFilterStock(!filterStock)},
            {k:"filterNav",label:"🚢 En tránsito",st:filterNav,fn:()=>setFilterNav(!filterNav)},
          ].map(f=>(
            <button key={f.k} onClick={f.fn} style={{
              padding:"7px 13px",borderRadius:9,fontSize:11,fontWeight:700,cursor:"pointer",fontFamily:"inherit",
              border:`1px solid ${f.st?"#3b82f6":"#e2e8f0"}`,
              background:f.st?"#eff6ff":"#fff",color:f.st?"#1d4ed8":"#64748b",
              transition:"all 0.15s",
            }}>{f.label}</button>
          ))}
          {(filterStock||filterNav||cat!=="Todos"||search) && (
            <button onClick={()=>{setSearch("");setCat("Todos");setFilterStock(false);setFilterNav(false);}} style={{
              padding:"7px 13px",borderRadius:9,fontSize:11,fontWeight:600,cursor:"pointer",fontFamily:"inherit",
              border:"1px solid #fee2e2",background:"#fef2f2",color:"#dc2626",
            }}>✕ Limpiar</button>
          )}
        </div>

        <div style={{fontSize:12,color:"#94a3b8",marginBottom:12}}>{filtered.length} referencias</div>

        {/* Product list */}
        <div style={{display:"flex",flexDirection:"column",gap:7}}>
          {filtered.map(p=><Card key={p.c+p.cat} p={p} isVendedor={isVendedor} />)}
          {filtered.length===0 && (
            <div style={{textAlign:"center",padding:"60px 20px",color:"#94a3b8"}}>
              <div style={{fontSize:32,marginBottom:10}}>🔍</div>
              <div style={{fontSize:15,fontWeight:600}}>Sin resultados</div>
            </div>
          )}
        </div>

        {/* Distributor footer */}
        {!isVendedor && (
          <div style={{marginTop:28,padding:"14px 18px",background:"#fff",borderRadius:12,border:"1px solid #e2e8f0",fontSize:12,color:"#64748b",lineHeight:1.6}}>
            <strong style={{color:"#1e293b"}}>¿Quieres reservar material?</strong> Contacta a tu asesor MeUp con el código del producto y la cantidad. Las fechas ETA son estimadas. Disp. 1 = primer contenedor en llegar · Disp. 2 = siguiente.
          </div>
        )}
      </div>
    </div>
  );
}

// ── ROOT ─────────────────────────────────────────────────────────────────────
export default function App() {
  const [user, setUser] = useState(null);
  const [showLogin, setShowLogin] = useState(false);

  if (!user && !showLogin) {
    return (
      <div style={{minHeight:"100vh",background:"#0a0f1e",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",fontFamily:"'DM Sans',sans-serif",padding:20}}>
        <style>{`@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=DM+Mono:wght@500;700&display=swap');*{box-sizing:border-box}`}</style>
        <div style={{background:"#fff",borderRadius:16,padding:"14px 28px",marginBottom:20,boxShadow:"0 4px 24px rgba(0,0,0,0.4)"}}>
          <img src={LOGO} alt="MeUp" style={{height:52,display:"block"}} />
        </div>
        <h1 style={{color:"#f1f5f9",fontSize:22,fontWeight:800,margin:"0 0 8px",letterSpacing:"-0.02em",textAlign:"center"}}>Portal de Inventario</h1>
        <p style={{color:"#64748b",fontSize:14,margin:"0 0 40px",textAlign:"center"}}>Selecciona cómo quieres acceder</p>
        <div style={{display:"flex",gap:16,flexWrap:"wrap",justifyContent:"center",maxWidth:480}}>
          <button onClick={()=>setUser({type:"vendedor",name:"Equipo MeUp"})} style={{
            flex:1,minWidth:200,padding:"22px 28px",background:"linear-gradient(135deg,#1e3a5f,#1d4ed8)",
            border:"1px solid #2563eb44",borderRadius:18,color:"#fff",cursor:"pointer",fontFamily:"inherit",
            textAlign:"left",boxShadow:"0 8px 32px rgba(29,78,216,0.3)",transition:"transform 0.15s",
          }}>
            <div style={{fontSize:28,marginBottom:8}}>👤</div>
            <div style={{fontSize:16,fontWeight:800,marginBottom:4}}>Vendedor MeUp</div>
            <div style={{fontSize:12,color:"#93c5fd",lineHeight:1.4}}>Acceso completo · Stock + reservas + navegación + alertas</div>
          </button>
          <button onClick={()=>setShowLogin(true)} style={{
            flex:1,minWidth:200,padding:"22px 28px",background:"linear-gradient(135deg,#1c1917,#292524)",
            border:"1px solid #44403c",borderRadius:18,color:"#fff",cursor:"pointer",fontFamily:"inherit",
            textAlign:"left",transition:"transform 0.15s",
          }}>
            <div style={{fontSize:28,marginBottom:8}}>🏪</div>
            <div style={{fontSize:16,fontWeight:800,marginBottom:4}}>Distribuidor</div>
            <div style={{fontSize:12,color:"#a8a29e",lineHeight:1.4}}>Acceso con correo y contraseña · Stock disponible y tránsito</div>
          </button>
        </div>
      </div>
    );
  }

  if (showLogin && !user) {
    return <LoginScreen onLogin={u=>{setUser(u);setShowLogin(false);}} />;
  }

  return <Dashboard user={user} onLogout={()=>{setUser(null);setShowLogin(false);}} />;
}
